#!/usr/bin/env python3
"""Compile and execute the complete POSIX VCR TU with controlled synchronous OS bindings."""

import argparse
import errno
import hashlib
import json
from pathlib import Path
import shlex
import struct
import subprocess


ROOT = Path(__file__).resolve().parents[3]
HERE = Path(__file__).resolve().parent


def packet_oracle():
    # Independent v2 wire description: little-endian u32 version, u8 event, fixed 32-bit scalars.
    # Numeric event tags are pinned literals, not imported from or generated by the implementation.
    return (struct.pack("<I", 2) + b"\x00" + struct.pack("<d", 1.25)
            + b"\x14\x06event\0" + struct.pack("<i", 3) + b"\x00\xff\x7e"
            + b"\x13" + struct.pack("<i", 3)
            + b"\x13" + struct.pack("<ii", -1, errno.EAGAIN)
            + b"\x12" + struct.pack("<i", 3) + b"r\0x"
            + b"\x12" + struct.pack("<ii", -1, errno.ECONNRESET)
            + b"\x01" + struct.pack("<i", 2) + b"rx\x01\x01\x02\x03\x04"
            + b"\x13" + struct.pack("<i", 2147483647)
            + b"\x14\x04end\0" + struct.pack("<i", 0))


def control_oracle():
    return (struct.pack("<I", 2) + b"\x02\x04sync" + struct.pack("<i", 3) + b"dbg"
            + b"\x07" + struct.pack("<i", 8) + b" -steam\0"
            + b"\x06" + struct.pack("<i", 5) + b"exec\0"
            + b"\x06" + struct.pack("<i", -1)
            + b"\x0f\x01" + struct.pack("<I", 0xdeadbeef)
            + b"\x0e\x01" + struct.pack("<IIi", 0xfedcba98, 0x80000000, -2147483648)
            + b"\x0e\x00")


def run(arguments, log, cwd=ROOT):
    try:
        result = subprocess.run(arguments, cwd=cwd, text=True, errors="replace", stdout=subprocess.PIPE,
                                stderr=subprocess.STDOUT, timeout=30)
        code = result.returncode
        output = result.stdout
    except subprocess.TimeoutExpired as error:
        code = 124
        output = str(error)
    log.write_text(shlex.join(map(str, arguments)) + "\n\n" + output)
    return code, output


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--source", type=Path, default=ROOT / "src/tier0/vcrmode_posix.cpp")
    parser.add_argument("--legacy-reference", action="store_true")
    parser.add_argument("--phase", choices=["red", "green"], required=True)
    parser.add_argument("--whole-tu-commands", type=Path)
    args = parser.parse_args()
    output = args.output.resolve()
    output.mkdir(parents=True, exist_ok=True)
    source = args.source.resolve()
    if args.legacy_reference:
        assert source != ROOT / "src/tier0/vcrmode_posix.cpp"
    oracle = packet_oracle()
    (output / "independent-v2.bin").write_bytes(oracle)
    controls = control_oracle()
    (output / "independent-controls-v2.bin").write_bytes(controls)
    unnamed = struct.pack("<I", 2) + b"\x14\xff" + struct.pack("<i", 1) + b"\x5a"
    (output / "independent-unnamed-v2.bin").write_bytes(unnamed)
    results = []
    profiles = [("arm64-release", "arm64", ["-O2", "-DNDEBUG"]),
                ("arm64-debug", "arm64", ["-O0", "-g", "-D_DEBUG"]),
                ("arm64-sanitizers", "arm64", ["-O1", "-g", "-fsanitize=address,undefined",
                                               "-fno-sanitize-recover=all", "-fno-omit-frame-pointer"]),
                ("x86_64-release", "x86_64", ["-O2", "-DNDEBUG"]),
                ("x86_64-debug", "x86_64", ["-O0", "-g", "-D_DEBUG"])]
    if args.phase == "red":
        profiles = [("arm64-debug", "arm64", ["-O0", "-g", "-D_DEBUG"])]
    cases = ["record", "replay", "record-controls", "replay-controls", "empty", "high-offset", "seek-error",
             "tell-error", "write-error", "read-error", "open-error", "flush-error", "event-write-error",
             "result-write-error", "errno",
             "native-result", "null-generic", "disabled", "bad-truncated-header", "bad-truncated-event",
             "bad-truncated-send-error", "bad-truncated-recv", "bad-recv-over-capacity", "bad-negative-generic",
             "bad-unterminated-name", "bad-negative-command", "bad-truncated-command", "bad-wrong-event", "bad-short-read",
             "bad-truncated-game", "bad-game-marker", "bad-debug-length", "bad-negative-cmd-exec",
             "bad-unterminated-command", "bad-truncated-address", "bad-address-marker", "bad-unknown-version",
             "bad-invalid-event"]
    for name, architecture, flags in profiles:
        binary = output / name
        command = ["/usr/bin/clang++", "-std=c++14", "-arch", architecture, "-mmacosx-version-min=14.0",
                   "-DTIER0_DLL", "-DOSX", "-DPOSIX", "-Wall", "-Wextra", "-Werror", "-Wno-unknown-pragmas",
                   "-Werror=shorten-64-to-32", "-Werror=pointer-to-int-cast", "-ffp-model=precise", "-ffp-contract=off",
                   "-Wno-overriding-option",
                   "-I" + str(ROOT / "src/public"), '-DCSE_VCR_SOURCE="' + str(source) + '"'] + flags
        if args.legacy_reference:
            command += ["-Wno-error=shorten-64-to-32"]
        command += [str(HERE / "vcr_tests.cpp"), "-o", str(binary)]
        code, _ = run(command, output / (name + "-compile.log"))
        results.append({"profile": name, "case": "compile", "exit": code})
        if code:
            continue
        for case in cases:
            path = output / (name + "-" + case + ".bin")
            if case in ["replay", "replay-controls"]:
                path.write_bytes(controls if case == "replay-controls" else oracle)
            code, _ = run([str(binary), case, str(path)], output / (name + "-" + case + ".log"))
            if code == 0 and case == "record" and path.read_bytes() != oracle:
                code = 125
            if code == 0 and case == "record-controls" and path.read_bytes() != controls:
                code = 125
            if code == 0 and case == "null-generic" and path.read_bytes() != unnamed:
                code = 125
            results.append({"profile": name, "case": case, "exit": code})
            if case == "high-offset" and path.exists():
                # Sparse input is tested, then released so the packet does not retain an 8-GiB apparent file.
                path.unlink()
    if args.whole_tu_commands:
        entries = json.loads(args.whole_tu_commands.read_text())
        sanitized = dict(next(entry for entry in entries if entry["mode"] == "release"))
        sanitized["mode"] = "sanitizers"
        sanitized["args"] = sanitized["args"] + ["-fsanitize=address,undefined", "-fno-sanitize-recover=all",
                                                "-fno-omit-frame-pointer", "-g"]
        for entry in entries + [sanitized]:
            command = entry["args"][:]
            command[command.index("-o") + 1] = str(output / (entry["mode"] + "-actual.o"))
            code, _ = run(command, output / (entry["mode"] + "-whole-tu.log"), Path(entry["cwd"]))
            results.append({"profile": "actual-" + entry["mode"], "case": "whole-tu", "exit": code})
    receipt = {"source": str(source), "source_sha256": hashlib.sha256(source.read_bytes()).hexdigest(),
               "test_sha256": hashlib.sha256((HERE / "vcr_tests.cpp").read_bytes()).hexdigest(),
               "oracle_sha256": hashlib.sha256(oracle).hexdigest(), "oracle_bytes": len(oracle),
               "control_oracle_sha256": hashlib.sha256(controls).hexdigest(), "control_oracle_bytes": len(controls),
               "unnamed_oracle_sha256": hashlib.sha256(unnamed).hexdigest(), "unnamed_oracle_bytes": len(unnamed),
               "legacy_reference": args.legacy_reference, "results": results}
    (output / "receipt.json").write_text(json.dumps(receipt, indent=2) + "\n")
    for result in results:
        print(json.dumps(result))
    if args.phase == "red":
        return 0 if any(result["case"] != "compile" and result["exit"] != 0 for result in results) else 1
    return 0 if all(result["exit"] == 0 for result in results) else 1


if __name__ == "__main__":
    raise SystemExit(main())
